-- Adds username support: a `username` column on `users` (nullable — unset
-- on every pre-existing account until they go through the "choose a
-- username" gate or edit their profile) plus its case-insensitive unique
-- index, and a denormalized `inviteeUsername` column on `trip_shares` for
-- displaying who was invited without a second lookup.
--
-- NOT generated by `drizzle-kit generate`: this repo's migration journal
-- (drizzle/meta/_journal.json) is already out of sync with two tables that
-- were added directly in production (catalog_requests, free_ai_usage —
-- see drizzle/0008_add_catalog_requests.sql and drizzle/0009_free_ai_usage.sql,
-- neither tracked in the journal). Running `drizzle-kit generate` as-is
-- produces a migration that tries to CREATE TABLE them again. This file is
-- hand-written to contain ONLY the actual new changes; drizzle/schema.ts
-- has already been updated to match it. Worth reconciling the journal
-- separately at some point, but that's unrelated to this feature.
--
-- Run with:
--   psql "$DATABASE_URL" -f scripts/sql/add-username.sql

BEGIN;

ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "username" varchar(20);

-- Case-insensitive uniqueness. Postgres allows multiple NULLs in a unique
-- index, so every pre-existing account (username still unset) is unaffected.
CREATE UNIQUE INDEX IF NOT EXISTS "users_username_lower_idx" ON "users" (lower("username"));

ALTER TABLE "trip_shares" ADD COLUMN IF NOT EXISTS "inviteeUsername" varchar(20);

COMMIT;
